"""Write the browser's event codes from shared_features/registry.yaml. python tools/generate_client_codes.py"""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from shared_features import ENUMS

OUTPUT = ROOT / "frontend" / "app" / "editor" / "capture" / "codes.ts"


def render() -> str:
    lines = [
        "// Generated by tools/generate_client_codes.py from shared_features/registry.yaml.",
        "// Do not edit by hand: change the registry and run the script again.",
    ]
    for name, spec in ENUMS.items():
        members = spec.get("values") or spec["flags"]
        lines.append("")
        lines.append(f"export const {name} = {{")
        lines.extend(f"  {member}: {code}," for member, code in members.items())
        lines.append("} as const;")
    return "\n".join(lines) + "\n"


def main() -> None:
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(render(), encoding="utf-8")
    print(f"{OUTPUT.relative_to(ROOT)}: {len(ENUMS)} code lists")


if __name__ == "__main__":
    main()
